mapper.select:
select * from ( select A.PRD_DESIGN_ID as prdDesignId, A.REQUIREMENT_ID as requirementId, A.PRD_DESIGN_SERIAL_NAME as prdDesignSerialName, A.PRD_BASE_GOAL as prdBaseGoal, A.PRD_CHARATER as prdCharater, A.RAISE_TYPE as raiseType, A.INVEST_NATURE as investNature, A.OPERATE_MODE as operateMode, A.TAR_CUSTOMER_TYPE as tarCustomerType, A.TAR_INVESTOR as tarInvestor, A.RSK_LEVEL as rskLevel, A.OPEN_DESCRIBE as openDescribe, A.PRD_TERM as prdTerm, A.PLAN_ISSUE_DATE as planIssueDate, A.PLAN_ISSUE_SCALE as planIssueScale, A.SALE_AREA as saleArea, A.BASE_RULE_INFO as baseRuleInfo, A.FEE_RATE as feeRate, A.TOFF_START as toffStart, A.HUGE_RED_RATIO as hugeRedRatio, A.OTHER as other, A.DATA_STATUS as dataStatus, 'New' AS WORKFLOW_ID, A.CREATE_USER as createUser, A.CREATE_DEPT as createDept, A.CREATE_TIME as createTime, A.UPDATE_USER as updateUser, A.UPDATE_TIME as updateTime FROM PRODUCT_DESIGN_INFO A inner join PRODUCT_REQUIREMENT B on A.REQUIREMENT_ID=B.REQUIREMENT_ID left join WFL_PRODUCT_DESIGN_INFO C on C.PRD_DESIGN_ID=A.PRD_DESIGN_ID where C.PRD_DESIGN_ID is null
and A.PRD_DESIGN_ID like '%'||#{prdDesignId}||'%'
and A.PRD_DESIGN_SERIAL_NAME like '%'||#{prdDesignSerialName}||'%'
and A.RAISE_TYPE = #{raiseType}
and A.INVEST_NATURE = #{investNature}
and A.OPERATE_MODE = #{operateMode}
and A.TAR_CUSTOMER_TYPE = #{SaletargetDeclare}
)

select A.DATA_STATUS as dataStatus, A.REQUIREMENT_ID as requirementId, A.REQUIREMENT_BASIS as requirementBasis, A.REQUIREMENT_DATE as requiremenDate, A.TAR_CUSTOMER as tarCustomer, A.PRD_SCALE as prdScale, A.PRD_PERIOD as prdPeriod, A.PRD_RATE as prdRate, A.PRD_REQUIREMENT_DETIAL as prdRequirementDetial, A.REQUIREMENT_SOURCE as requirementSource, B.FEASIBILITY_STATUS as feasibilityStatus, B.FEASIBILITY_TYPE as feasibilitType from PRODUCT_REQUIREMENT A left join PRODUCT_REQUIREMENT_ADD B on A.REQUIREMENT_ID=B.REQUIREMENT_ID where 1=1
and A.DATA_STATUS=#{dataStatus,jdbcType=VARCHAR}
and B.REPORT_STATUS=#{REPORT_STATUS2_1}
